1192	+using System.Text.Json;
1193	+using Microsoft.EntityFrameworkCore;
1194	+using seed_a_backend.Api.Domain;
1195	+using seed_a_backend.Api.Infrastructure.SeedModels;
1196	+
1197	+namespace seed_a_backend.Api.Infrastructure;
1198	+
1199	+public class SeedDataImporter(AppDbContext db)
1200	+{
1201	+    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
1202	+
1203	+    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
1204	+    {
1205	+        if (await db.Venues.AnyAsync(ct))
1206	+        {
1207	+            return;
1208	+        }
1209	+
1210	+        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
1211	+        var data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions)
1212	+            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
1213	+
1214	+        await ImportAsync(data, ct);
1215	+    }
1216	+
1217	+    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
1218	+    {
1219	+        var eventsById = new Dictionary<string, Event>();
1220	+        var venues = new List<Venue>();
1221	+
1222	+        foreach (var venueDto in data.Spielstaetten)
1223	+        {
1224	+            var venue = new Venue { Name = venueDto.Name };
1225	+            var roomsById = new Dictionary<string, Room>();
1226	+
1227	+            foreach (var roomDto in venueDto.Raeume)
1228	+            {
1229	+                var room = new Room
1230	+                {
1231	+                    Name = roomDto.Name,
1232	+                    RowLabels = roomDto.Reihen,
1233	+                    ColumnCount = roomDto.Spalten,
1234	+                    AisleColumns = roomDto.Gang?.Spalten ?? new List<int>(),
1235	+                };
1236	+                venue.Rooms.Add(room);
1237	+                roomsById[roomDto.Id] = room;
1238	+            }
1239	+
1240	+            foreach (var eventDto in data.Veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
1241	+            {
1242	+                var room = roomsById[eventDto.RaumId];
1243	+                var @event = new Event
1244	+                {
1245	+                    Titel = eventDto.Titel,
1246	+                    Beschreibung = eventDto.Beschreibung,
1247	+                    Zeitpunkt = eventDto.Zeitpunkt,
1248	+                    DauerMinuten = eventDto.DauerMinuten,
1249	+                    Altersfreigabe = eventDto.Altersfreigabe,
1250	+                };
1251	+
1252	+                foreach (var priceCategoryDto in eventDto.Preiskategorien)
1253	+                {
1254	+                    @event.PriceCategories.Add(new PriceCategory
1255	+                    {
1256	+                        Name = priceCategoryDto.Name,
1257	+                        Preis = priceCategoryDto.Preis,
1258	+                    });
1259	+                }
1260	+
1261	+                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
1262	+                {
1263	+                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
1264	+                    @event.BookingPositions.Add(new BookingPosition
1265	+                    {
1266	+                        RowLabel = rowLabel,
1267	+                        ColumnNumber = columnNumber,
1268	+                        BookingId = null,
1269	+                        PriceCategoryId = null,
1270	+                        CancelledAtUtc = null,
1271	+                    });
1272	+                }
1273	+
1274	+                room.Events.Add(@event);
1275	+                eventsById[eventDto.Id] = @event;
1276	+            }
1277	+
1278	+            venues.Add(venue);
1279	+        }
1280	+
1281	+        db.Venues.AddRange(venues);
1282	+        await db.SaveChangesAsync(ct);
1283	+    }
1284	+
1285	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
1286	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
1287	+    {
1288	+        var digitsStart = 0;
1289	+        while (digitsStart < sitzplatz.Length && !char.IsDigit(sitzplatz[digitsStart]))
1290	+        {
1291	+            digitsStart++;
1292	+        }
1293	+
1294	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length)
1295	+        {
1296	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
1297	+        }
1298	+
1299	+        var rowLabel = sitzplatz[..digitsStart];
1300	+        var columnNumber = int.Parse(sitzplatz[digitsStart..]);
1301	+        return (rowLabel, columnNumber);
1302	+    }
1303	+}
