4	namespace seed_a_backend.Tests;
5	
6	/// <summary>Bewacht AD-5: Domain/ bleibt frei von EF-Core-/ASP.NET-Core-Typen und -Attributen.</summary>
7	public class DomainDependencyDirectionTests
8	{
9	    private static readonly Type[] DomainTypes =
10	    [
11	        typeof(Venue), typeof(Room), typeof(Event), typeof(PriceCategory), typeof(Booking), typeof(BookingPosition),
12	    ];
13	
14	    [Fact]
15	    public void Domain_Typen_haben_keine_Properties_mit_EF_Core_oder_AspNetCore_Typen()
16	    {
17	        foreach (var type in DomainTypes)
18	        {
19	            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
20	            {
21	                Assert.False(IsForbiddenNamespace(property.PropertyType.Namespace),
22	                    $"{type.Name}.{property.Name} referenziert einen unerlaubten Typ aus '{property.PropertyType.Namespace}'.");
23	            }
24	        }
25	    }
26	
27	    [Fact]
28	    public void Domain_Typen_tragen_keine_Datenannotationen()
29	    {
30	        foreach (var type in DomainTypes)
31	        {
32	            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
33	            {
34	                foreach (var attribute in property.GetCustomAttributes())
35	                {
36	                    Assert.False(IsForbiddenNamespace(attribute.GetType().Namespace),
37	                        $"{type.Name}.{property.Name} trägt ein Attribut aus '{attribute.GetType().Namespace}'.");
38	                }
39	            }
40	        }
41	    }
42	
43	    private static bool IsForbiddenNamespace(string? ns) =>
44	        ns is not null && (ns.StartsWith("Microsoft.AspNetCore", StringComparison.Ordinal)
45	            || ns.StartsWith("Microsoft.EntityFrameworkCore", StringComparison.Ordinal));
46	}
