3	using seed_a_backend.Api.Domain;
4	using seed_a_backend.Api.Infrastructure.SeedModels;
5	
6	namespace seed_a_backend.Api.Infrastructure;
7	
8	public class SeedDataImporter(AppDbContext db)
9	{
10	    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
11	
12	    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
13	    {
14	        if (await db.Venues.AnyAsync(ct))
15	        {
16	            return;
17	        }
18	
19	        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
20	        var data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions)
21	            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
22	
23	        await ImportAsync(data, ct);
24	    }
25	
26	    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
27	    {
28	        var eventsById = new Dictionary<string, Event>();
29	        var venues = new List<Venue>();
30	
31	        foreach (var venueDto in data.Spielstaetten)
32	        {
33	            var venue = new Venue { Name = venueDto.Name };
34	            var roomsById = new Dictionary<string, Room>();
35	
36	            foreach (var roomDto in venueDto.Raeume)
37	            {
38	                var room = new Room
39	                {
40	                    Name = roomDto.Name,
41	                    RowLabels = roomDto.Reihen,
42	                    ColumnCount = roomDto.Spalten,
43	                    AisleColumns = roomDto.Gang?.Spalten ?? new List<int>(),
44	                };
45	                venue.Rooms.Add(room);
46	                roomsById[roomDto.Id] = room;
47	            }
48	
49	            foreach (var eventDto in data.Veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
50	            {
51	                var room = roomsById[eventDto.RaumId];
52	                var @event = new Event
53	                {
54	                    Titel = eventDto.Titel,
55	                    Beschreibung = eventDto.Beschreibung,
56	                    Zeitpunkt = eventDto.Zeitpunkt,
57	                    DauerMinuten = eventDto.DauerMinuten,
58	                    Altersfreigabe = eventDto.Altersfreigabe,
59	                };
60	
61	                foreach (var priceCategoryDto in eventDto.Preiskategorien)
62	                {
63	                    @event.PriceCategories.Add(new PriceCategory
64	                    {
65	                        Name = priceCategoryDto.Name,
66	                        Preis = priceCategoryDto.Preis,
67	                    });
68	                }
69	
70	                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
71	                {
72	                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
73	                    @event.BookingPositions.Add(new BookingPosition
74	                    {
75	                        RowLabel = rowLabel,
76	                        ColumnNumber = columnNumber,
77	                        BookingId = null,
78	                        PriceCategoryId = null,
79	                        CancelledAtUtc = null,
80	                    });
81	                }
82	
83	                room.Events.Add(@event);
84	                eventsById[eventDto.Id] = @event;
85	            }
86	
87	            venues.Add(venue);
88	        }
89	
90	        db.Venues.AddRange(venues);
91	        await db.SaveChangesAsync(ct);
92	    }
93	
94	    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
95	    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
96	    {
97	        var digitsStart = 0;
98	        while (digitsStart < sitzplatz.Length && !char.IsDigit(sitzplatz[digitsStart]))
99	        {
100	            digitsStart++;
101	        }
102	
103	        if (digitsStart == 0 || digitsStart == sitzplatz.Length)
104	        {
105	            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
106	        }
107	
108	        var rowLabel = sitzplatz[..digitsStart];
109	        var columnNumber = int.Parse(sitzplatz[digitsStart..]);
110	        return (rowLabel, columnNumber);
111	    }
112	}
